<script lang="ts">
  import {onMount} from 'svelte';
  import {api,request,setToken,stream,download,cleanConfiguration} from './api';
  import type {Configuration,Conversation,Profile,Provider,ServerEvent,Side} from './api';
  import {markdown} from './markdown';
  import ConfigForm from './ConfigForm.svelte';
  let connected=false,token='',error='',notice='',busy=false;
  let page='dashboard',theme='dark',query='',filter='',providerFilter='',messageQuery='';
  let status:any=null,conversations:Conversation[]=[],profiles:Profile[]=[],catalogs:Provider[]=[];
  let config:Configuration,form:Configuration,selected:Conversation|null=null;
  let confirmPaid=false,resumePaid=false,resumeTurns=20,resumeOpen=false;
  let controller:AbortController|undefined;
  const sides:Side[]=['A','B'];
  $: billable=form&&Object.values(form.participants).some(p=>profiles.find(v=>v.id===p.profile_id)?.billable);
  $: visible=conversations.filter(c=>(c.config.topic+' '+c.id).toLowerCase().includes(query.toLowerCase())&&(!filter||c.status===filter)&&(!providerFilter||Object.values(c.config.participants).some(p=>p.provider===providerFilter)));
  $: totalTokens=conversations.reduce((sum,c)=>sum+Object.values(c.stats.speakers).reduce((s,p)=>s+p.input_tokens+p.output_tokens,0),0);
  $: totalSeconds=conversations.reduce((sum,c)=>sum+c.stats.seconds,0);
  const labels:Record<string,string>={completed:'Completata',running:'In corso',starting:'In avvio',interrupted:'Interrotta',paused:'In pausa',failed:'Errore',stopped:'Arrestata',ready:'Pronta'};
  function date(value:string){return new Date(value).toLocaleString('it-IT',{dateStyle:'medium',timeStyle:'short'});}
  function showError(e:unknown){error=e instanceof Error?e.message:String(e);}
  async function action(fn:()=>Promise<void>){error='';busy=true;try{await fn();}catch(e){showError(e);}finally{busy=false;}}
  async function refresh(){[status,conversations,profiles,catalogs]=await Promise.all([api('/status'),api('/conversations'),api('/profiles'),api('/models')]);}
  async function login(){await action(async()=>{setToken(token.trim());config=await api('/settings');form=structuredClone(config);await refresh();connected=true;token='';const id=new URLSearchParams(location.hash.slice(1)).get('conversation');if(id)await openConversation(id);});}
  function logout(){controller?.abort();setToken('');connected=false;selected=null;conversations=[];profiles=[];error='';}
  async function diagnose(){await action(async()=>{catalogs=(await api('/doctor','POST',{})).providers;notice='Cataloghi aggiornati senza inferenze.';await refresh();});}
  function navigate(next:string){controller?.abort();page=next;error='';notice='';if(next==='new'){form=structuredClone(config);confirmPaid=false;}location.hash='';}
  async function create(demo=false){await action(async()=>{if(!demo&&billable&&!confirmPaid)throw Error('Conferma esplicitamente i costi delle API selezionate.');if(!confirm(demo?'Avviare una simulazione sul server?':`Avviare ${form.max_turns} messaggi su “${form.topic}”?`))return;const result=await api('/conversations','POST',{configuration:cleanConfiguration(form),confirm_paid:confirmPaid,demo});await openConversation(result.id);await refresh();});}
  function onEvent(event:ServerEvent){if(!selected||selected.id!==event.conversation_id)return;const d=event.data;
    if(event.type==='state.snapshot')selected=d;
    else if(event.type==='message.delta'){if(!selected.partial)selected.partial={speaker:d.speaker,model:d.model,text:''};selected.partial.text+=d.delta;}
    else if(event.type==='turn.started'){selected.partial={speaker:d.speaker,model:selected.config.participants[d.speaker as Side]?.model||'',text:''};selected.status='running';}
    else if(event.type==='message.completed'){if(selected.messages.length<d.index)selected.messages=[...selected.messages,d.message];selected.partial=undefined;}
    else if(event.type==='stats.updated')selected.stats=d;
    else if(['conversation.completed','conversation.stopped','conversation.failed','conversation.paused'].includes(event.type)){selected.status=d.status;selected.error=d.error;}
    selected={...selected!};
  }
  async function openConversation(id:string){controller?.abort();selected=await api(`/conversations/${id}`);resumeTurns=selected!.messages.length+10;resumePaid=false;resumeOpen=false;messageQuery='';page='conversation';location.hash='conversation='+id;controller=new AbortController();stream(id,onEvent,controller.signal,()=>notice='Connexion interrompue. Reconnexion…').then(()=>refresh()).catch(showError);}
  async function control(operation:string){if(!selected)return;await action(async()=>{await api(`/conversations/${selected!.id}/${operation}`,'POST',{});selected=await api(`/conversations/${selected!.id}`);await refresh();});}
  async function resume(){if(!selected)return;await action(async()=>{await api(`/conversations/${selected!.id}/preflight`,'POST',{});await api(`/conversations/${selected!.id}/resume`,'POST',{max_turns:resumeTurns,confirm_paid:resumePaid});await openConversation(selected!.id);await refresh();});}
  async function remove(c:Conversation){if(!confirm(`Eliminare definitivamente “${c.config.topic}” e gli export sul server?`))return;await action(async()=>{await request(`/conversations/${c.id}`,'DELETE');if(selected?.id===c.id){selected=null;navigate('history');}await refresh();});}
  async function saveSettings(){await action(async()=>{config=await api('/settings','PUT',cleanConfiguration(form));notice='Impostazioni del server salvate.';});}
  async function saveProfiles(){await action(async()=>{profiles=await api('/profiles','PUT',{profiles:profiles.map(({billable,...p})=>p)});notice='Profili salvati sul server. Gli storici mantengono la propria configurazione.';});}
  function addProfile(){profiles=[...profiles,{id:'profile-'+Date.now()+'-'+Math.random().toString(16).slice(2),name:'Nuovo profilo',provider:'ollama',model:'',url:'http://localhost:11434',api_key_env:''}];}
  function providerChanged(p:Profile){p.url=p.provider==='openai'?'https://api.openai.com/v1':p.provider==='openrouter'?'https://openrouter.ai/api/v1':p.provider==='ollama'?'http://localhost:11434':'';p.api_key_env=p.provider==='openai'?'OPENAI_API_KEY':p.provider==='openrouter'?'OPENROUTER_API_KEY':'';profiles=[...profiles];}
  async function copy(text:string){try{await navigator.clipboard.writeText(text);notice='Testo copiato.';}catch{error='Copia automatica non disponibile: seleziona il testo o usa HTTPS.';}}
  function toggleTheme(){theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('alterecho-theme',theme);}
  onMount(()=>{theme=localStorage.getItem('alterecho-theme')||'dark';document.documentElement.dataset.theme=theme;const timer=setInterval(()=>{if(connected&&!busy)refresh().catch(showError);},8000);return()=>{clearInterval(timer);controller?.abort();};});
</script>

<svelte:head><title>AlterEcho · {page==='conversation'?selected?.config.topic:'Conversazioni tra modelli'}</title></svelte:head>
{#if !connected}
  <main class="login"><div class="brand-mark">a<span>e</span></div><p class="eyebrow">ALTERECHO / 1.0</p><h1>Due prospettive.<br/>Una conversazione.</h1><p class="muted">Collegati al tuo server per creare, seguire e riprendere i dialoghi tra modelli.</p><form on:submit|preventDefault={login}><label>Token del servizio<input type="password" autocomplete="off" required bind:value={token} placeholder="Inserisci il token di AlterEcho"/></label><button class="primary" disabled={busy}>Collega al server <span>→</span></button></form><p class="footnote">Il token si trova in <code>server-token</code> nella configurazione del server, oppure in <code>ALTERECHO_TOKEN</code>. Rimane soltanto nella memoria di questa pagina.</p>{#if error}<div role="alert" class="alert error">{error}</div>{/if}<button class="text-button" on:click={toggleTheme}>Tema {theme==='dark'?'chiaro':'scuro'}</button></main>
{:else}
  <div class="shell"><aside><a href="/" class="brand" on:click|preventDefault={()=>navigate('dashboard')}><span class="brand-symbol">a<span>e</span></span><strong>AlterEcho<small>CONVERSAZIONI TRA MODELLI</small></strong></a><nav aria-label="Navigazione principale">{#each [['dashboard','Panoramica','◫'],['new','Nuova conversazione','＋'],['history','Cronologia','◷'],['settings','Impostazioni','⚙']] as item}<button class:current={page===item[0]} on:click={()=>{navigate(item[0]);if(item[0]==='settings')form=structuredClone(config);}}><span>{item[2]}</span>{item[1]}</button>{/each}</nav><div class="sidebar-bottom"><span class="connection-dot"></span> Server connesso<small>{status?.version} · {location.host}</small><div class="sidebar-actions"><button on:click={toggleTheme}>{theme==='dark'?'☀ Chiaro':'◐ Scuro'}</button><button on:click={logout}>Scollega</button></div></div></aside>
  <main class="workspace"><header><div><p class="eyebrow">IL TUO SPAZIO DI DIALOGO</p><h1>{page==='dashboard'?'Panoramica':page==='new'?'Nuova conversazione':page==='history'?'Cronologia':page==='settings'?'Impostazioni':'Conversazione'}</h1></div><div class="header-actions"><span class="status-pill"><span class="connection-dot"></span>Server attivo</span>{#if page!=='new'}<button class="primary" on:click={()=>navigate('new')}>＋ Nuovo dialogo</button>{/if}</div></header>
  {#if error}<div class="alert error" role="alert">{error}<button aria-label="Chiudi errore" on:click={()=>error=''}>×</button></div>{/if}{#if notice}<div class="alert" role="status">{notice}<button aria-label="Chiudi notifica" on:click={()=>notice=''}>×</button></div>{/if}

  {#if page==='dashboard'}
    <section class="welcome"><div><p class="eyebrow">PROSPETTIVE CHE SI INCONTRANO</p><h2>Lascia spazio alle idee.</h2><p>Affianca due modelli, scegli un argomento<br/>e segui il dialogo mentre prende forma.</p><button class="primary" on:click={()=>navigate('new')}>Crea una conversazione <span>↗</span></button></div><div class="orbits" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><span class="orb a">A</span><span class="orb b">B</span><span class="orbit-center">↔</span></div></section>
    <section class="metrics" aria-label="Statistiche"><article><span>Conversazioni attive</span><strong>{conversations.filter(c=>c.active).length.toString().padStart(2,'0')}</strong><small>Continuano anche senza client</small></article><article><span>Dialoghi salvati</span><strong>{conversations.length.toString().padStart(2,'0')}</strong><small>Una cronologia condivisa</small></article><article><span>Token misurati</span><strong>{totalTokens.toLocaleString('it-IT')}</strong><small>Input e output disponibili</small></article><article><span>Tempo di generazione</span><strong>{totalSeconds.toFixed(1)}<em> s</em></strong><small>Somma dei turni completati</small></article></section>
    <div class="section-heading"><h2>Provider e modelli</h2><button disabled={busy} on:click={diagnose}>↻ Verifica cataloghi</button></div><section class="provider-grid">{#each profiles as p}<article class="provider-card"><div class="provider-icon">{p.provider==='codex'?'⌘':p.provider==='ollama'?'◉':'↗'}</div><div><h3>{p.name}</h3><p>{p.provider}{p.billable?' · API a consumo':''}</p><small>{catalogs.find(c=>c.profile_id===p.id)?.available?`${catalogs.find(c=>c.profile_id===p.id)?.models.length} modelli disponibili`:catalogs.find(c=>c.profile_id===p.id)?.error||'Da verificare'}</small></div><span class:ok={catalogs.find(c=>c.profile_id===p.id)?.available} class="provider-dot"></span></article>{/each}</section>
    <div class="section-heading"><h2>Conversazioni recenti</h2><button class="text-button" on:click={()=>navigate('history')}>Tutta la cronologia →</button></div>
  {/if}

  {#if page==='dashboard'||page==='history'}
    {#if page==='history'}<div class="filters"><input aria-label="Cerca cronologia" placeholder="Cerca per argomento o ID…" bind:value={query}/><select aria-label="Filtra stato" bind:value={filter}><option value="">Tutti gli stati</option>{#each Object.entries(labels) as [key,label]}<option value={key}>{label}</option>{/each}</select><select aria-label="Filtra provider" bind:value={providerFilter}><option value="">Tutti i provider</option><option>codex</option><option>ollama</option><option>openai</option><option>openrouter</option></select></div>{/if}
    <section class="history-list">{#each (page==='dashboard'?conversations.slice(0,5):visible) as c}<article class="history-row"><button class="history-main" on:click={()=>action(()=>openConversation(c.id))}><span class="conversation-icon">↔</span><div><h3>{c.config.topic}</h3><p>{Object.values(c.config.participants).map(p=>p.name||p.provider).join(' ↔ ')} <span>·</span> {c.message_count??c.messages?.length??0} messaggi <span>·</span> {date(c.created_at)}</p></div></button><span class="badge" class:running={c.active}>{labels[c.status]||c.status}</span><button class="row-arrow" aria-label="Apri conversazione" on:click={()=>action(()=>openConversation(c.id))}>↗</button></article>{:else}<div class="empty"><span>↔</span><h3>Il prossimo dialogo inizia qui.</h3><p>Le conversazioni di tutti i client appariranno in questo spazio.</p><button on:click={()=>navigate('new')}>Crea il primo dialogo</button></div>{/each}</section>
    {#if status?.unreadable_histories}<p class="error-text">{status.unreadable_histories} storici non leggibili conservati intatti. Controlla i file sul server.</p>{/if}
  {/if}

  {#if page==='new'&&form}<section class="card"><div class="section-heading"><div><h2>Imposta il dialogo</h2><p class="muted">Due interlocutori, una memoria comune.</p></div><button on:click={diagnose} disabled={busy}>↻ Aggiorna modelli</button></div><form on:submit|preventDefault={()=>create()}><ConfigForm bind:value={form} {profiles} {catalogs}/>{#if billable}<div class="paid-notice"><strong>API a consumo selezionate</strong><p>OpenAI e OpenRouter possono addebitare costi all'account configurato sul server.</p><label class="check"><input type="checkbox" bind:checked={confirmPaid}/>Confermo l'utilizzo delle API a consumo per questo dialogo.</label></div>{/if}<div class="form-footer"><small>Il dialogo continuerà se chiudi questa pagina.</small><button type="button" disabled={busy} on:click={()=>create(true)}>Prova demo</button><button class="primary" disabled={busy||(billable&&!confirmPaid)}>Avvia conversazione →</button></div></form></section>{/if}

  {#if page==='conversation'&&selected}<section class="conversation-heading"><div><span class="badge" class:running={selected.active}>{labels[selected.status]||selected.status}</span><h2>{selected.config.topic}</h2><p class="muted">{selected.id} · {date(selected.created_at)}</p><div class="participant-tags">{#each sides as side}<span class:tag-b={side==='B'}>{side} · {selected.config.participants[side].name} <small>{selected.config.participants[side].model}</small></span>{/each}</div></div><div class="controls">{#if selected.active}<button disabled={busy||selected.pause_requested} on:click={()=>control('pause')}>{selected.pause_requested?'Pausa richiesta':'Pausa tra i turni'}</button><button class="danger" disabled={busy} on:click={()=>control('stop')}>Arresta</button>{:else if !selected.demo}<button disabled={busy} on:click={()=>resumeOpen=!resumeOpen}>Riprendi</button>{/if}<button disabled={selected.active||busy} class="text-button danger" on:click={()=>remove(selected!)}>Elimina</button></div></section>
    <div class="conversation-stats"><span>{selected.messages.length} / {selected.config.max_turns} messaggi</span><span>{selected.stats.seconds.toFixed(2)} s</span>{#each Object.entries(selected.stats.speakers) as [side,stats]}<span>{side}: {stats.input_tokens} input · {stats.output_tokens} output token</span>{/each}</div>
    {#if selected.error}<div role="alert" class="alert error">{selected.error}</div>{/if}
    {#if resumeOpen}<section class="card resume-form"><h3>Riprendi dal checkpoint del server</h3><label>Nuovo massimo totale<input type="number" min={selected.messages.length+1} max="10000" bind:value={resumeTurns}/></label>{#if Object.values(selected.config.participants).some(p=>p.billable)}<label class="check"><input type="checkbox" bind:checked={resumePaid}/>Confermo i costi delle API per la ripresa.</label>{/if}<button class="primary" disabled={busy} on:click={resume}>Verifica e riprendi</button></section>{/if}
    <div class="filters"><input aria-label="Cerca nei messaggi" placeholder="Cerca nei messaggi…" bind:value={messageQuery}/><div class="export-buttons"><span>Esporta</span>{#each ['html','md','txt','json'] as fmt}<button on:click={()=>action(async()=>{await download(selected!.id,fmt);})}>{fmt.toUpperCase()}</button>{/each}</div></div>
    <section class="messages" aria-live="polite">{#each selected.messages as m,index}{#if m.text.toLowerCase().includes(messageQuery.toLowerCase())}<article class="message" class:message-b={m.speaker==='B'}><div class="message-heading"><span class="side" class:side-b={m.speaker==='B'}>{m.speaker}</span><div><strong>{selected.config.participants[m.speaker].name}</strong><small>{m.model} · #{index+1}</small></div><button class="text-button" on:click={()=>copy(m.text)}>Copia</button></div><div class="markdown">{@html markdown(m.text)}</div><footer>{m.seconds.toFixed(2)} s · input {m.usage.input_tokens??'—'} · output {m.usage.output_tokens??'—'} token {#if m.usage.tokens_per_second}· {m.usage.tokens_per_second.toFixed(1)} token/s{/if}{#if m.usage.load_seconds!==undefined} · caricamento {m.usage.load_seconds.toFixed(3)} s{/if}</footer></article>{/if}{/each}{#if selected.partial}<article class="message partial" class:message-b={selected.partial.speaker==='B'}><div class="message-heading"><strong>{selected.partial.speaker} · {selected.partial.model}</strong><span class="badge">{selected.active?'Risposta in arrivo':'Risposta parziale · non completata'}</span></div><pre>{selected.partial.text||'In attesa del modello…'}</pre></article>{/if}</section>
  {/if}

  {#if page==='settings'&&form}<section class="card"><h2>Preferenze condivise</h2><p class="muted">Le modifiche valgono per i prossimi dialoghi di CLI e browser.</p><form on:submit|preventDefault={saveSettings}><ConfigForm bind:value={form} {profiles} {catalogs} compact/><div class="form-footer"><button class="primary" disabled={busy}>Salva sul server</button></div></form></section><section class="card"><div class="section-heading"><div><h2>Profili dei provider</h2><p class="muted">Inserisci solo il nome della variabile d'ambiente. Le chiavi si configurano sul server.</p></div><button on:click={addProfile}>＋ Profilo</button></div>{#each profiles as p}<fieldset class="profile-editor"><legend>{p.name}</legend><div class="form-grid"><label>Nome<input bind:value={p.name}/></label><label>Provider<select bind:value={p.provider} on:change={()=>providerChanged(p)}><option>codex</option><option>ollama</option><option>openai</option><option>openrouter</option></select></label><label>Modello preferito<input bind:value={p.model}/></label>{#if p.provider==='ollama'}<label>Endpoint autorizzato dal server<input bind:value={p.url}/></label>{:else if p.provider==='openai'||p.provider==='openrouter'}<label>Nome variabile della chiave<input bind:value={p.api_key_env}/></label>{/if}</div><button class="text-button danger" on:click={()=>profiles=profiles.filter(v=>v.id!==p.id)}>Rimuovi profilo</button></fieldset>{/each}<button class="primary" disabled={busy} on:click={saveProfiles}>Salva profili</button></section>{/if}
  <footer class="workspace-footer">AlterEcho <span>Un server. Tutte le tue prospettive.</span><small>Le generazioni avvengono sul server configurato.</small></footer>
  </main></div>
{/if}
